10	use super::ResolutionContext;
11	
12	/// Re-export chains in real code are shallow (one or two barrel hops); this
13	/// only guards against a pathological or cyclic `export * from` graph.
14	const MAX_REEXPORT_DEPTH: u8 = 8;
15	
16	/// Counts real invocations of `follow_reexports`, so tests can assert the
17	/// visited-set is actually collapsing shared-descendant re-exploration
18	/// (linear in graph size) instead of just checking wall-clock time — the
19	/// per-call work here is cheap enough, and oxc_resolver's own path cache
20	/// absorbing enough of the redundant filesystem cost, that wall-clock alone
21	/// doesn't reliably distinguish "linear" from "branching_factor^depth". Only calls for files under the scoped directory
22	/// count, so resolution in tests running in parallel does not inflate the number.
23	#[cfg(test)]
24	static FOLLOW_REEXPORTS_CALLS: std::sync::Mutex<Option<(Utf8PathBuf, usize)>> = std::sync::Mutex::new(None);
25	
26	#[cfg(test)]
27	pub(crate) fn reset_follow_reexports_call_count(scope: &Utf8Path) {
28	    *FOLLOW_REEXPORTS_CALLS.lock().unwrap_or_else(|p| p.into_inner()) = Some((scope.to_owned(), 0));
29	}
30	
31	#[cfg(test)]
32	pub(crate) fn follow_reexports_call_count() -> usize {
33	    FOLLOW_REEXPORTS_CALLS.lock().unwrap_or_else(|p| p.into_inner()).as_ref().map_or(0, |(_, n)| *n)
34	}
