36	/// Resolve `name` to its canonical `(file_path, name)` pair.
37	/// Returns `None` if `name` is a local declaration (not imported).
38	pub(super) fn resolve_to_canonical(
39	    name: &str,
40	    consuming_file: &Utf8Path,
41	    ctx: &ResolutionContext,
42	    diagnostics: &mut Vec<Diagnostic>,
43	) -> Option<(Utf8PathBuf, String)> {
44	    if let Some(import_ref) = ctx.import_map.find_import(consuming_file, name) {
45	        let resolved_file = resolve_import_specifier(&import_ref.specifier, consuming_file, ctx, diagnostics)?;
46	        let canonical_name = import_ref.exported_name.to_string();
47	        let mut visited = FxHashSet::default();
48	        return Some(follow_reexports(resolved_file, canonical_name, ctx, diagnostics, &mut visited, 0));
49	    }
50	
51	    // Namespace-import member access: `import * as React from "react"` then a
52	    // reference to `React.DependencyList`. `find_import` only tracks the
53	    // namespace binding itself ("React", with `exported_name == "*"`) — a
54	    // literal dotted name like "React.DependencyList" is never itself a
55	    // binding, so the lookup above always misses it. Split off the namespace
56	    // prefix and route the member name through the namespace's own import
57	    // specifier instead.
58	    let (namespace, member) = name.split_once('.')?;
59	    let namespace_ref = ctx.import_map.find_import(consuming_file, namespace)?;
60	    // A named import of a namespace (`import { Menu as MenuPrimitive } from "./ui"`, then `MenuPrimitive.Root`):
61	    // the member's name in that module is `Menu.Root`, which a namespace re-export or declaration answers.
62	    // A default import is the module's namespace for an `export =` module (`import React from "react"` under
63	    // `esModuleInterop`, antd's spelling), so `React.CSSProperties` names the same member `import * as React` does.
64	    let member = if namespace_ref.exported_name == "*" || namespace_ref.exported_name == "default" {
65	        member.to_owned()
66	    } else {
67	        format!("{}.{member}", namespace_ref.exported_name)
68	    };
69	    let resolved_file = resolve_import_specifier(&namespace_ref.specifier, consuming_file, ctx, diagnostics)?;
70	    let mut visited = FxHashSet::default();
71	    Some(follow_reexports(resolved_file, member, ctx, diagnostics, &mut visited, 0))
72	}
73	
74	/// The name `file` itself declares `name` under: a type, or any value it exports (`export function f`,
75	/// `export { g as f }` gives `g`). `None` when the file only re-exports it, or doesn't have it.
76	fn declared_name(ctx: &ResolutionContext, file: &Utf8Path, name: &str) -> Option<String> {
77	    if ctx.named_types.is_declared_at(file, name) {
78	        return Some(name.to_owned());
79	    }
80	    ctx.import_map.local_export(file, name)
81	}
82	
83	/// A directly-imported name may land on a barrel file (`export { X } from
84	/// './x'` or `export * from './x'`) that doesn't declare `name` itself —
85	/// ubiquitous in real component libraries' `index.ts` files. Follow the
86	/// re-export chain until we reach a file that actually declares `name`, or
87	/// run out of chain to follow — in which case the original (barrel_file,
88	/// name) is returned unchanged, so the caller's existing "cannot resolve"
89	/// diagnostic still fires exactly as it did before this existed.
90	fn follow_reexports(
91	    file: Utf8PathBuf,
92	    name: String,
93	    ctx: &ResolutionContext,
94	    diagnostics: &mut Vec<Diagnostic>,
95	    visited: &mut FxHashSet<(Utf8PathBuf, CompactString)>,
96	    depth: u8,
97	) -> (Utf8PathBuf, String) {
98	    #[cfg(test)]
99	    if let Some((scope, count)) = FOLLOW_REEXPORTS_CALLS.lock().unwrap_or_else(|p| p.into_inner()).as_mut()
100	        && file.starts_with(&*scope)
101	    {
102	        *count += 1;
103	    }
104	
105	    super::deps::record(&file);
106	    if depth >= MAX_REEXPORT_DEPTH {
107	        return (file, name);
108	    }
109	    if let Some(declared) = declared_name(ctx, &file, &name) {
110	        return (file, declared);
111	    }
112	    // A package's re-export stubs are not in the layer; the loader's answer for them stands in (the persisted index).
113	    if let Some(answer) = ctx.dependencies.as_ref().and_then(|layer| layer.export_of(&file, &name)) {
114	        return match answer {
115	            Some((declaring_file, declared_name)) => (declaring_file.clone(), declared_name.to_string()),
116	            None => (file, name),
117	        };
118	    }
119	    // Real barrels commonly share descendants (several sub-barrels wildcarding
120	    // the same underlying `types.ts`, say) — without this, re-exploring an
121	    // already-visited (file, name) pair from a different parent multiplies out
122	    // to branching_factor^depth calls instead of one call per graph node. This
123	    // also subsumes cycle detection: a cycle revisits a pair by definition.
124	    if !visited.insert((file.clone(), CompactString::from(name.as_str()))) {
125	        return (file, name);
126	    }
127	    match ctx.import_map.resolve_reexport_chain(&file, &name) {
128	        Some(ReExportStep::Named { source_specifier, source_name }) => {
129	            let Some(next_file) = resolve_import_specifier(&source_specifier, &file, ctx, diagnostics) else {
130	                return (file, name);
131	            };
132	            follow_reexports(next_file, source_name, ctx, diagnostics, visited, depth + 1)
133	        }
134	        Some(ReExportStep::Wildcards(specifiers)) => {
135	            for specifier in &specifiers {
136	                let Some(candidate_file) = resolve_import_specifier(specifier, &file, ctx, diagnostics) else {
137	                    continue;
138	                };
139	                let (resolved_file, resolved_name) =
140	                    follow_reexports(candidate_file, name.clone(), ctx, diagnostics, visited, depth + 1);
141	                // A hop that found the declaration renames it to its local name; one that didn't returns `name`.
142	                if resolved_name != name || declared_name(ctx, &resolved_file, &resolved_name).is_some() {
143	                    return (resolved_file, resolved_name);
144	                }
145	            }
146	            (file, name)
147	        }
148	        None => (file, name),
149	    }
150	}
