152	/// Look up an interface by canonical `(file, name)`, falling back to a
153	/// `React.`-namespace-qualified key. `@types/react` declares everything
154	/// inside `declare namespace React { ... }`, so real declarations are keyed
155	/// "React.HTMLAttributes" even though nothing imports them that way — a plain
156	/// `import type { HTMLAttributes } from "react"` binds the bare name.
157	pub(super) fn lookup_interface<'g>(
158	    ctx: &'g ResolutionContext,
159	    canonical_file: &str,
160	    canonical_name: &str,
161	) -> Option<&'g CollectedInterface> {
162	    super::deps::record(Utf8Path::new(canonical_file));
163	    ctx.named_types.lookup_interface(Utf8Path::new(canonical_file), canonical_name)
164	}
