178	/// Same as `lookup_interface`, for type aliases. Returns the name that
179	/// actually matched (bare or `React.`-qualified) alongside the value, since
180	/// callers also need it to look up `type_alias_params` under the same
181	/// `(file, name)`.
182	pub(super) fn lookup_type_alias<'g>(
183	    ctx: &'g ResolutionContext,
184	    canonical_file: &str,
185	    canonical_name: &str,
186	) -> Option<(CompactString, &'g CollectedTypeAlias)> {
187	    super::deps::record(Utf8Path::new(canonical_file));
