191	/// Same as `lookup_interface`, but also falls back to TypeScript's own ambient
192	/// lib files (`ctx.ambient_global_files`) when the name isn't found via
193	/// import/same-file resolution — e.g. `HTMLDivElement`, declared ambiently in
194	/// `lib.dom.d.ts`, is never imported, so `resolve_to_canonical` never resolves
195	/// it to that file and `canonical_file` stays the consuming file instead.
196	pub(super) fn lookup_interface_including_ambient<'g>(
197	    ctx: &'g ResolutionContext,
198	    canonical_file: &str,
199	    canonical_name: &str,
200	) -> Option<&'g CollectedInterface> {
201	    super::deps::record(Utf8Path::new(canonical_file));
202	    ctx.named_types.lookup_interface_including_ambient(
203	        Utf8Path::new(canonical_file),
204	        canonical_name,
205	        &ctx.ambient_global_files,
206	    )
207	}
