209	/// Look up a name directly on TypeScript's own ambient lib files
210	/// (`ctx.ambient_global_files` — `lib.es5.d.ts`/`lib.dom.d.ts`), by bare name
211	/// only (these are ambient globals, never namespace-qualified). Deliberately
212	/// separate from — and only ever consulted AFTER — every other resolution
213	/// path (imports, same-file declarations, the well-known-TS-utility-type
214	/// silent list): `Record`/`Partial`/etc. are themselves declared here too
215	/// (`Record<K, T> = { [P in K]: T }`, a mapped type this tool can't expand),
216	/// so checking this first would intercept those already-handled names and
217	/// degrade them to Opaque instead of leaving them to the existing shortcuts.
218	pub(super) fn lookup_ambient_global<'g>(ctx: &'g ResolutionContext, name: &str) -> Option<AmbientGlobalLookup<'g>> {
219	    match ctx.named_types.lookup_ambient(&ctx.ambient_global_files, name)? {
220	        crate::named_type_index::AmbientMatch::Interface => Some(AmbientGlobalLookup::Interface),
221	        crate::named_type_index::AmbientMatch::TypeAlias(alias) => Some(AmbientGlobalLookup::TypeAlias(alias)),
222	    }
223	}
