230	/// What a specifier resolves to from one directory.
231	#[derive(Clone)]
232	pub(crate) enum ModuleResolution {
233	    /// A package's type declarations, outside the project.
234	    PackageTypes(Utf8PathBuf),
235	    /// A file of the project, or a module resolved by path.
236	    File(Utf8PathBuf),
237	    /// The resolver's error.
238	    Unresolved(String),
239	}
