241	/// Use `oxc_resolver` to turn an import specifier into an absolute file path.
242	pub(super) fn resolve_import_specifier(
243	    specifier: &str,
244	    from_file: &Utf8Path,
245	    ctx: &ResolutionContext,
246	    diagnostics: &mut Vec<Diagnostic>,
247	) -> Option<Utf8PathBuf> {
248	    super::deps::record_module_resolution();
249	    let from_dir = from_file.parent()?;
250	    // Every file of a directory shares its nearest tsconfig, so the directory is as good a key as the file.
251	    let key = (Box::from(from_dir.as_str()), Box::from(specifier));
252	    let resolution = match ctx.module_resolutions.get(&key) {
253	        Some(cached) => cached.clone(),
254	        None => {
255	            let resolution = resolve_module(specifier, from_file, ctx);
256	            ctx.module_resolutions.insert(key, resolution.clone());
257	            resolution
258	        }
259	    };
260	    match resolution {
261	        ModuleResolution::PackageTypes(path) => Some(path),
262	        ModuleResolution::File(path) => {
263	            super::deps::record(&path);
264	            Some(path)
265	        }
266	        ModuleResolution::Unresolved(error) => {
267	            diagnostics.push(
268	                Diagnostic::new(
269	                    DiagnosticSeverity::Warning,
270	                    DiagnosticCode::UnresolvableImport,
271	                    format!("Cannot resolve '{}' from '{}'", specifier, from_file),
272	                )
273	                .with_file(from_file.to_string())
274	                .with_help(format!("Resolution error: {}", error)),
275	            );
276	            None
277	        }
278	    }
279	}
