281	/// Resolve `specifier` as imported by `from_file`; the file, not its directory, is what finds the nearest tsconfig.
282	fn resolve_module(specifier: &str, from_file: &Utf8Path, ctx: &ResolutionContext) -> ModuleResolution {
283	    resolve_module_with(&ctx.oxc_resolver, &ctx.types_first_resolver, specifier, from_file)
284	}
285	
286	/// `resolve_module` with explicit resolvers (`ModuleResolvers`): the dependency loader resolves before a
287	/// `ResolutionContext` exists and must find the same files the resolver later does.
288	pub(crate) fn resolve_module_with(
289	    main: &oxc_resolver::Resolver,
290	    types_first: &oxc_resolver::Resolver,
291	    specifier: &str,
292	    from_file: &Utf8Path,
293	) -> ModuleResolution {
294	    // Bare package specifiers (not relative/absolute) need real TypeScript
295	    // declaration resolution: prefer a real .d.ts over whatever JS entry point
296	    // the package's own "main"/"exports" happens to point to, and fall back to
297	    // the separate `@types/<package>` package when the package ships no types
298	    // of its own at all — e.g. "react": its package.json has no "types" field
299	    // and no "types" export condition, so a plain `resolve()` below lands on
300	    // `index.js`, and a named type-only import like `HTMLAttributes` can never
301	    // be found there.
302	    if !specifier.starts_with('.') && !specifier.starts_with('/') {
303	        let types = super::react::resolve_package_types_file(main, types_first, from_file, specifier);
304	        if let Some(path) = types {
305	            return match Utf8PathBuf::from_path_buf(std::path::PathBuf::from(path)) {
306	                Ok(path) => ModuleResolution::PackageTypes(path),
